'use strict';
// Account profile: name, photo, contact and trading details. Stored in journal_settings ("workspace_profile").
const PF={data:{settings:{},revision:0},busy:false,uploading:false};
const PF_REGIONS='AF AX AL DZ AS AD AO AI AQ AG AR AM AW AU AT AZ BS BH BD BB BY BE BZ BJ BM BT BO BQ BA BW BR IO BN BG BF BI CV KH CM CA KY CF TD CL CN CX CC CO KM CG CD CK CR CI HR CU CW CY CZ DK DJ DM DO EC EG SV GQ ER EE SZ ET FK FO FJ FI FR GF PF GA GM GE DE GH GI GR GL GD GP GU GT GG GN GW GY HT VA HN HK HU IS IN ID IR IQ IE IM IL IT JM JP JE JO KZ KE KI KP KR KW KG LA LV LB LS LR LY LI LT LU MO MG MW MY MV ML MT MH MQ MR MU YT MX FM MD MC MN ME MS MA MZ MM NA NR NP NL NC NZ NI NE NG NU NF MK MP NO OM PK PW PS PA PG PY PE PH PN PL PT PR QA RE RO RU RW BL SH KN LC MF PM VC WS SM ST SA SN RS SC SL SG SX SK SI SB SO ZA GS SS ES LK SD SR SJ SE CH SY TW TJ TZ TH TL TG TK TO TT TN TR TM TC TV UG UA AE GB US UM UY UZ VU VE VN VG VI WF EH YE ZM ZW'.split(' ');
function pfCountries(){let names;try{names=new Intl.DisplayNames(undefined,{type:'region'});}catch{names=null;}return PF_REGIONS.map(code=>[code,names?.of(code)||code]).sort((a,b)=>a[1].localeCompare(b[1]));}
function pfZones(){try{return Intl.supportedValuesOf('timeZone');}catch{return [Intl.DateTimeFormat().resolvedOptions().timeZone];}}
const pfName=p=>[p.firstName,p.lastName].filter(Boolean).join(' ');
function pfInitials(p){const n=(p.displayName||pfName(p)).trim();if(n)return n.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();return (userEmail||'T').trim()[0].toUpperCase();}

async function loadProfile(){try{PF.data=await wsApi('profile');}catch{PF.data={settings:{},revision:0};}pfPaintAvatar();}
// Top-bar avatar: photo if set, otherwise initials.
function pfPaintAvatar(){const el=$('#tbAvatar');if(!el)return;const p=PF.data.settings||{};
  if(p.photo){el.textContent='';el.style.backgroundImage=`url("/${p.photo}")`;el.classList.add('has-photo');}else{el.style.backgroundImage='';el.classList.remove('has-photo');el.textContent=pfInitials(p);}
  el.title=(p.displayName||pfName(p)||userEmail||'Account');}

function renderProfileEditor(){const host=$('#profileEditor');if(!host)return;const p={...PF.data.settings},zone=p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone;
  const f=(label,name,value,attrs='')=>`<label class="tf-field">${label}<input name="${name}" value="${esc(value||'')}" ${attrs}></label>`;
  const sel=(label,name,options,current,placeholder)=>`<label class="tf-field">${label}<select name="${name}"><option value="">${placeholder}</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
  host.innerHTML=`<form id="pfForm" class="pf-form" novalidate>
   <div class="pf-photo"><div class="pf-avatar" id="pfAvatar"></div><div><b>Profile photo</b><p class="muted">PNG, JPG, GIF or WebP. Shown in the top bar.</p>
    <div class="pf-photo-actions"><button type="button" class="btn ghost" id="pfPhotoBtn">${p.photo?'Change photo':'Upload photo'}</button>${p.photo?'<button type="button" class="ws-link" id="pfPhotoRemove">Remove</button>':''}<input type="file" id="pfPhotoFile" accept="image/png,image/jpeg,image/gif,image/webp" hidden></div></div></div>
   <div class="pf-grid">
    ${f('First name','firstName',p.firstName,'autocomplete="given-name" maxlength="60"')}${f('Surname','lastName',p.lastName,'autocomplete="family-name" maxlength="60"')}
    ${f('Display name','displayName',p.displayName,'maxlength="60" placeholder="How your name appears in the app"')}
    <label class="tf-field">Email<input value="${esc(userEmail||'')}" disabled title="Your login email"></label>
    ${f('Mobile number','mobile',p.mobile,'type="tel" autocomplete="tel" inputmode="tel" maxlength="24" placeholder="Include your country code"')}
    ${sel('Country','country',pfCountries(),p.country,'Select country')}
    ${f('Zip / postal code','zip',p.zip,'autocomplete="postal-code" maxlength="12" placeholder="e.g. 560001"')}
    ${sel('Time zone','timezone',pfZones().map(z=>[z,z.replace(/_/g,' ')]),zone,'Select time zone')}
    ${sel('Trading experience','experience',['Under 1 year','1-3 years','3-5 years','5+ years'].map(x=>[x,x]),p.experience,'Select')}
    ${f('Markets traded','markets',p.markets,'maxlength="200" placeholder="e.g. BTC perps, Bank Nifty options"')}
    <label class="tf-field pf-full">Bio<textarea name="bio" rows="3" maxlength="500" placeholder="A line about your trading style">${esc(p.bio||'')}</textarea></label>
   </div>
   <div class="pf-foot"><span class="ws-form-status" id="pfStatus" role="status" aria-live="polite"></span><button type="submit" class="btn" id="pfSave">Save profile</button></div></form>`;
  PF.photo=p.photo||'';pfPaintPreview();
  const form=$('#pfForm');form.oninput=()=>{$('#pfStatus').textContent='Unsaved changes';pfPaintPreview();};
  $('#pfPhotoBtn').onclick=()=>$('#pfPhotoFile').click();
  $('#pfPhotoRemove')?.addEventListener('click',()=>{PF.photo='';$('#pfStatus').textContent='Photo removed. Save to keep this change.';pfPaintPreview();$('#pfPhotoRemove').remove();$('#pfPhotoBtn').textContent='Upload photo';});
  $('#pfPhotoFile').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(!/^image\/(png|jpe?g|gif|webp)$/.test(file.type)){$('#pfStatus').textContent='Use a PNG, JPG, GIF or WebP image.';return;}
    PF.uploading=true;$('#pfSave').disabled=true;$('#pfStatus').textContent='Uploading photo…';
    try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const response=await fetch('/api/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data})});const result=await response.json();if(!response.ok||!result.path)throw Error(result.error||'Upload failed');PF.photo=result.path;$('#pfStatus').textContent='Photo ready. Save to keep it.';$('#pfPhotoBtn').textContent='Change photo';pfPaintPreview();}
    catch(error){$('#pfStatus').textContent=error.message||'Upload failed';}finally{PF.uploading=false;$('#pfSave').disabled=false;}};
  form.onsubmit=async event=>{event.preventDefault();if(PF.busy||PF.uploading)return;const values=Object.fromEntries(new FormData(form));const settings={firstName:values.firstName.trim(),lastName:values.lastName.trim(),displayName:values.displayName.trim(),mobile:values.mobile.trim(),country:values.country,zip:values.zip.trim(),timezone:values.timezone,experience:values.experience,markets:values.markets.trim(),bio:values.bio.trim(),photo:PF.photo};
    PF.busy=true;$('#pfSave').disabled=true;$('#pfStatus').textContent='Saving…';
    try{PF.data=await wsApi('profile','PUT',{settings,revision:PF.data.revision});$('#pfStatus').textContent='Profile saved.';pfPaintAvatar();}
    catch(error){$('#pfStatus').textContent=error.message;}finally{PF.busy=false;$('#pfSave').disabled=false;}};}
function pfPaintPreview(){const el=$('#pfAvatar');if(!el)return;const form=$('#pfForm'),p=form?Object.fromEntries(new FormData(form)):{};
  if(PF.photo){el.style.backgroundImage=`url("/${PF.photo}")`;el.textContent='';}else{el.style.backgroundImage='';el.textContent=pfInitials(p);}}

