// After plans load, redraw the routine so it shows the Active plan (it is first drawn before plans arrive).
const pfBaseLoadWorkspace=loadWorkspace;loadWorkspace=async(...args)=>{const ok=await pfBaseLoadWorkspace(...args);await loadProfile();wsRefreshFx();if(typeof routineState!=='undefined'&&routineState)renderRoutinePanel();return ok;};
const pfBaseSetAvatar=setAvatar;setAvatar=email=>{pfBaseSetAvatar(email);pfPaintAvatar();};
const pfBaseRenderSettings=renderSettings;renderSettings=function(){pfBaseRenderSettings();if(!PF.busy&&!PF.uploading&&!(($('#pfStatus')?.textContent||'').startsWith('Unsaved')))renderProfileEditor();};
